import sys

MOD = 998244353

def factor(x):
    res = {}
    p = 2
    while p * p <= x:
        while x % p == 0:
            res[p] = res.get(p, 0) + 1
            x //= p
        p += 1
    if x > 1:
        res[x] = res.get(x, 0) + 1
    return res

def prime_contribution(p, occurrences, n):
    # dp[h] is the total weight after normalization, with current height h.
    dp = {0: 1}
    vertices = 1
    processed_edges = 0

    for edge, exponent in occurrences:
        gap = edge - processed_edges
        if gap:
            for h in dp:
                dp[h] = dp[h] * pow(p, h * gap, MOD) % MOD
            vertices += gap
            processed_edges = edge

        nxt = {}
        for h, value in dp.items():
            # The exponent increases by exponent on this edge.
            nh = h + exponent
            nxt[nh] = (nxt.get(nh, 0) + value * pow(p, nh, MOD)) % MOD

            # Or it decreases.  If it passes the running minimum, normalize.
            if h >= exponent:
                nh = h - exponent
                nxt[nh] = (nxt.get(nh, 0) + value * pow(p, nh, MOD)) % MOD
            else:
                # The old vertices are all shifted upward by exponent-h.
                shift = (exponent - h) * vertices
                nxt[0] = (nxt.get(0, 0) + value * pow(p, shift, MOD)) % MOD

        dp = nxt
        vertices += 1
        processed_edges = edge + 1

    gap = n - 1 - processed_edges
    if gap:
        for h in dp:
            dp[h] = dp[h] * pow(p, h * gap, MOD) % MOD
    return sum(dp.values()) % MOD

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    by_prime = {}
    for i, a in enumerate(data[1:]):
        for p, e in factor(a).items():
            by_prime.setdefault(p, []).append((i, e))

    answer = 1
    for p, occurrences in by_prime.items():
        answer = answer * prime_contribution(p, occurrences, n) % MOD
    print(answer)

if __name__ == '__main__':
    main()

