def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:1 + n]
    limit = max(a, default=1)

    spf = list(range(limit + 1))
    for p in range(2, int(limit ** 0.5) + 1):
        if spf[p] == p:
            for v in range(p * p, limit + 1, p):
                if spf[v] == v:
                    spf[v] = p

    omega = [0] * (limit + 1)
    for v in range(2, limit + 1):
        omega[v] = omega[v // spf[v]] + 1

    nim_sum = 0
    for v in a:
        nim_sum ^= omega[v]
    print("Anna" if nim_sum else "Bruno")

