class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)
        good = [False] * (L + 1)
        for c in range(1, L + 1):
            x = c
            steps = 0
            while x != 1:
                x = x.bit_count()
                steps += 1
            good[c] = steps <= k - 1
        comb = [[0] * (L + 1) for _ in range(L + 1)]
        comb[0][0] = 1
        for i in range(1, L + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i-1][j-1] + comb[i-1][j]) % MOD
        ans = 0
        ones = 0
        for i, ch in enumerate(s):
            if ch == '1':
                rem = L - i - 1
                for c in range(1, L + 1):
                    if good[c] and 0 <= c - ones <= rem:
                        ans = (ans + comb[rem][c - ones]) % MOD
                ones += 1
        if good[ones]:
            pass
        return ans

