class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)
        good = [False] * (L + 1)
        for c in range(1, L + 1):
            x = c
            steps = 0
            while x != 1:
                x = x.bit_count()
                steps += 1
            good[c] = steps <= k - 1
        fact = [1] * (L + 1)
        invfact = [1] * (L + 1)
        for i in range(1, L + 1):
            fact[i] = fact[i - 1] * i % MOD
        invfact[L] = pow(fact[L], MOD - 2, MOD)
        for i in range(L, 0, -1):
            invfact[i - 1] = invfact[i] * i % MOD
        ans = 0
        ones = 0
        for i, ch in enumerate(s):
            if ch == '1':
                rem = L - i - 1
                for c in range(1, L + 1):
                    j = c - ones
                    if good[c] and 0 <= j <= rem:
                        ans = (ans + fact[rem] * invfact[j] * invfact[rem - j]) % MOD
                ones += 1
        return ans

