import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    pos = 2
    for _ in range(m):
        u, v = data[pos] - 1, data[pos + 1] - 1
        pos += 2
        rows[u] ^= 1 << v
        rows[v] ^= 1 << u

    # Put the adjacency matrix into reduced row echelon form over GF(2).
    pivots = []
    rank = 0
    for col in range(n):
        at = next((i for i in range(rank, n) if (rows[i] >> col) & 1), None)
        if at is None:
            continue
        rows[rank], rows[at] = rows[at], rows[rank]
        for i in range(n):
            if i != rank and ((rows[i] >> col) & 1):
                rows[i] ^= rows[rank]
        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    free = [c for c in range(n) if c not in pivot_set]
    values = [0] * n

    # Each nullspace basis vector is used as one binary bit of the answer.
    # Shifting by rank is unnecessary mathematically, but keeps all used bits
    # below N and gives the conventional sample-compatible representation.
    for j, f in enumerate(free):
        vec = 1 << f
        for i, pc in enumerate(pivots):
            if (rows[i] >> f) & 1:
                vec |= 1 << pc
        bit = 1 << (rank + j)
        for v in range(n):
            if (vec >> v) & 1:
                values[v] |= bit

    if any(x == 0 for x in values):
        print("No")
    else:
        print("Yes")
        print(*values)

if __name__ == "__main__":
    main()

