from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        # Counts larger than k are interchangeable, so cap them safely.
        cap = 10**15 + 1
        factorial = [1] * (n + 1)
        for i in range(1, n + 1):
            factorial[i] = min(cap, factorial[i - 1] * i)

        def completions(odd: int, even: int, required: int) -> int:
            # Once the next parity is fixed, the parity pattern is fixed.
            # The remaining values can then be permuted independently in
            # their odd and even positions.
            if required == 1:
                if odd != even and odd != even + 1:
                    return 0
            else:
                if even != odd and even != odd + 1:
                    return 0
            return min(cap, factorial[odd] * factorial[even])

        available = list(range(1, n + 1))
        odd = (n + 1) // 2
        even = n // 2
        required = None
        answer = []

        for _ in range(n):
            selected = False
            for value in available:
                parity = value & 1
                if required is not None and parity != required:
                    continue

                next_odd = odd - parity
                next_even = even - (1 - parity)
                block = completions(next_odd, next_even, 1 - parity)

                if k > block:
                    k -= block
                    continue

                answer.append(value)
                available.remove(value)
                odd, even = next_odd, next_even
                required = 1 - parity
                selected = True
                break

            if not selected:
                return []

        return answer

