class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        half = (n + 1) // 2
        coeff = [0] * half

        for i in range(half):
            coeff[i] = (
                pow(10, n - 1 - i, k)
                + (pow(10, i, k) if i != n - 1 - i else 0)
            ) % k

        # dp[i] is a bit mask of residues obtainable by positions i onward.
        dp = [0] * (half + 1)
        dp[half] = 1  # residue zero
        for i in range(half - 1, -1, -1):
            mask = 0
            first = (i == 0)
            for digit in range(1 if first else 0, 10):
                shift = (digit * coeff[i]) % k
                suffix = dp[i + 1]
                for residue in range(k):
                    if (suffix >> residue) & 1:
                        mask |= 1 << ((residue + shift) % k)
            dp[i] = mask

        # Greedily choose the largest possible left half.
        left = []
        needed = 0
        for i in range(half):
            lower = 1 if i == 0 else 0
            for digit in range(9, lower - 1, -1):
                shift = (digit * coeff[i]) % k
                next_needed = (needed - shift) % k
                if (dp[i + 1] >> next_needed) & 1:
                    left.append(str(digit))
                    needed = next_needed
                    break

        prefix = ''.join(left)
        if n % 2:
            return prefix + prefix[:-1][::-1]
        return prefix + prefix[::-1]

