from typing import List
from array import array

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        nxt = [n] * n
        st = []
        for i in range(n - 1, -1, -1):
            x = nums[i]
            while st and nums[st[-1]] <= x:
                st.pop()
            nxt[i] = st[-1] if st else n
            st.append(i)

        # Each entry i describes the constant running maximum on [i,nxt[i]).
        levels_u = [array('i', nxt)]
        base = array('q', (nums[i] * (nxt[i] - i) for i in range(n)))
        levels_s = [base]
        lg = n.bit_length()
        for z in range(1, lg):
            pu, ps = levels_u[-1], levels_s[-1]
            cu = array('i', [0]) * n
            cs = array('q', [0]) * n
            for i in range(n):
                q = pu[i]
                cu[i] = pu[q]
                cs[i] = ps[i] + ps[q]
            levels_u.append(cu)
            levels_s.append(cs)
        pref = [0] * (n + 1)
        for i, x in enumerate(nums):
            pref[i + 1] = pref[i] + x

        def cost(left, right):
            pos = left
            total = 0
            end = right + 1
            for z in range(lg - 1, -1, -1):
                q = levels_u[z][pos]
                if q <= end:
                    total += levels_s[z][pos]
                    pos = q
            if pos < end:
                total += nums[pos] * (end - pos)
            return total - (pref[end] - pref[left])

        ans = 0
        for r in range(n):
            lo, hi = 0, r
            while lo < hi:
                mid = (lo + hi) // 2
                if cost(mid, r) <= k:
                    hi = mid
                else:
                    lo = mid + 1
            if cost(lo, r) <= k:
                ans += r - lo + 1
        return ans

