class Solution:
    def maximumSubarrayXor(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        table = [array('I', [0]) * n for _ in range(n)]

        for i, value in enumerate(nums):
            table[i][i] = value

        # score(i,j) = score(i,j-1) XOR score(i+1,j)
        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                table[i][j] = table[i][j - 1] ^ table[i + 1][j]

        # Replace each score by the best score of any subarray it contains.
        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                best = table[i][j]
                if table[i + 1][j] > best:
                    best = table[i + 1][j]
                if table[i][j - 1] > best:
                    best = table[i][j - 1]
                table[i][j] = best

        return [table[left][right] for left, right in queries]

