import sys

class BIT:
    def __init__(self, m):
        self.m = m
        self.c = [0] * (m + 1)
        self.s = [0] * (m + 1)
        self.n = 0
        self.total = 0

    def add(self, p, value, delta):
        self.n += delta
        self.total += value * delta
        while p <= self.m:
            self.c[p] += delta
            self.s[p] += value * delta
            p += p & -p

    def sum_smallest(self, k, values):
        if k == 0:
            return 0
        p = 0
        count = 0
        total = 0
        step = 1 << (self.m.bit_length() - 1)
        while step:
            q = p + step
            if q <= self.m and count + self.c[q] < k:
                p = q
                count += self.c[q]
                total += self.s[q]
            step >>= 1
        return total + (k - count) * values[p]

    def score(self, values):
        return self.total - 2 * self.sum_smallest(self.n // 2, values)

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
