    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def matches(t):
            m = len(t)
            ok = bytearray(n + 1)
            if m == 0:
                ok[:] = b'\x01' * (n + 1)
                return ok

            prefix = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = prefix[j - 1]
                if t[i] == t[j]:
                    j += 1
                prefix[i] = j

            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = prefix[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    ok[i - m + 1] = 1
                    j = prefix[j - 1]
            return ok

        ma, mb, mc = matches(a), matches(b), matches(c)

        def next_occurrence(ok):
            nearest = n + 1
            result = [n + 1] * (n + 2)
            for i in range(n, -1, -1):
                if ok[i]:
                    nearest = i
                result[i] = nearest
            return result

        next_b = next_occurrence(mb)
        next_c = next_occurrence(mc)
        la, lb, lc = len(a), len(b), len(c)
        answer = n + 1

        for start in range(n + 1):
            if not ma[start]:
                continue
            b_start = next_b[start + la]
            if b_start > n:
                continue
            c_start = next_c[b_start + lb]
            if c_start <= n:
                answer = min(answer, c_start + lc - start)

        return -1 if answer == n + 1 else answer

