from itertools import combinations

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    a = data[2:]

    total = 0
    for value in a:
        total ^= value

    # Choosing K elements is equivalent, via the XOR of all elements,
    # to choosing the N-K omitted elements.
    r = min(k, n - k)
    if r == 0:
        print(total if k == n else 0)
        return

    best = -1
    use_complement = k > n // 2
    for chosen in combinations(a, r):
        value = 0
        for x in chosen:
            value ^= x
        if use_complement:
            value ^= total
        if value > best:
            best = value
    print(best)

