from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        # Generate the required postorder without recursion.
        post = []
        stack = [(0, 0)]
        while stack:
            x, next_child = stack[-1]
            if next_child < len(children[x]):
                y = children[x][next_child]
                stack[-1] = (x, next_child + 1)
                stack.append((y, 0))
            else:
                post.append(x)
                stack.pop()

        order_string = ''.join(s[x] for x in post)

        # Manacher radii for odd and even length palindromes.
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and order_string[i - k] == order_string[i + k]:
                k += 1
            odd[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and order_string[i - k - 1] == order_string[i + k]:
                k += 1
            even[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        # Each subtree is one contiguous interval in this postorder.
        subtree_size = [1] * n
        for x in reversed(post):
            if parent[x] != -1:
                subtree_size[parent[x]] += subtree_size[x]

        position = [0] * n
        for i, x in enumerate(post):
            position[x] = i

        answer = [False] * n
        for x in range(n):
            r = position[x]
            length = subtree_size[x]
            l = r - length + 1
            if length & 1:
                center = (l + r) // 2
                answer[x] = odd[center] >= length // 2 + 1
            else:
                center = (l + r + 1) // 2
                answer[x] = even[center] >= length // 2
        return answer

