import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        digits = len(str(n))
        low = 10 ** (digits - 1)
        high = 10 ** digits - 1

        prime = [True] * (high + 1)
        prime[0] = prime[1] = False
        limit = int(high ** 0.5)
        for p in range(2, limit + 1):
            if prime[p]:
                prime[p * p:high + 1:p] = [False] * (((high - p * p) // p) + 1)

        if prime[n] or prime[m]:
            return -1

        powers = [10 ** i for i in range(digits)]
        distance = {n: n}
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != distance.get(value):
                continue
            if value == m:
                return cost

            for place in powers:
                digit = (value // place) % 10
                if digit < 9:
                    nxt = value + place
                    if nxt <= high and not prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < distance.get(nxt, float('inf')):
                            distance[nxt] = new_cost
                            heapq.heappush(heap, (new_cost, nxt))
                if digit > 0:
                    nxt = value - place
                    if nxt >= low and not prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < distance.get(nxt, float('inf')):
                            distance[nxt] = new_cost
                            heapq.heappush(heap, (new_cost, nxt))

        return -1

