from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)

        # Z[i] is the LCP length of nums and nums[i:].
        z = [0] * n
        if n:
            z[0] = n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z[i] = min(right - i + 1, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > right:
                left, right = i, i + z[i] - 1

        # For a fixed i, lcp[i][j] is built from lcp[i+1][j+1].
        next_row = [0] * (n + 1)
        answer = 0
        for i in range(n - 2, 0, -1):
            row = [0] * (n + 1)
            for j in range(i + 1, n):
                if nums[i] == nums[j]:
                    row[j] = next_row[j + 1] + 1

            # nums[:i] is a prefix of nums[i:j].
            if z[i] >= i and 2 * i <= n - 1:
                answer += n - 2 * i

            # nums[i:j] is a prefix of nums[j:].  The length constraint is
            # j-i <= n-j, hence j <= (n+i)//2.
            hi = min(n - 1, (n + i) // 2)
            first_condition_possible = z[i] >= i
            for j in range(i + 1, hi + 1):
                if (not first_condition_possible or j < 2 * i) and row[j] >= j - i:
                    answer += 1
            next_row = row

        return answer

