class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        target = [False] * len(source)
        for i in targetIndices:
            target[i] = True

        m = len(pattern)
        inf = m + 1
        # dp[j] is the minimum number of target characters that must
        # be retained to match pattern[:j].
        dp = [inf] * (m + 1)
        dp[0] = 0

        for i, ch in enumerate(source):
            cost = 1 if target[i] else 0
            for j in range(m, 0, -1):
                if ch == pattern[j - 1]:
                    candidate = dp[j - 1] + cost
                    if candidate < dp[j]:
                        dp[j] = candidate

        return len(targetIndices) - dp[m]

