class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = set('aeiou')

        def at_most(limit: int) -> int:
            if limit < 0:
                return 0
            left = 0
            consonants = 0
            last = {v: -1 for v in vowels}
            result = 0

            for right, ch in enumerate(word):
                if ch in vowels:
                    last[ch] = right
                else:
                    consonants += 1

                while consonants > limit:
                    if word[left] not in vowels:
                        consonants -= 1
                    left += 1

                earliest_vowel = min(last.values())
                if earliest_vowel >= left:
                    result += earliest_vowel - left + 1

            return result

        return at_most(k) - at_most(k - 1)

