class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = set('aeiou')
        def at_most(limit):
            if limit < 0:
                return 0
            left = 0
            cons = 0
            last = {v: -1 for v in vowels}
            ans = 0
            for right, ch in enumerate(word):
                if ch in vowels:
                    last[ch] = right
                else:
                    cons += 1
                while cons > limit:
                    if word[left] not in vowels:
                        cons -= 1
                    left += 1
                earliest = min(last.values())
                if earliest >= left:
                    ans += earliest - left + 1
            return ans
        return at_most(k) - at_most(k - 1)

